package com.dm.backend.controller;import com.dm.backend.service.UserService;import com.dm.backend.vo.UserVo;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.HashMap;import java.util.Map;@RestController@RequestMapping("/api/auth")public class AuthC {    @Autowired    private UserService userService;    @PostMapping("/login")    public ResponseEntity<?> login(@RequestBody Map<String, String> body) {        String username = body.get("username");        String password = body.get("password");        UserVo user = userService.login(username, password);        if (user == null) {            return ResponseEntity.status(401).body("계정 정보가 일치하지 않습니다.");        }        Map<String, String> response = new HashMap<>();        response.put("role", user.getRole());        return ResponseEntity.ok(response);    }}